/* Guided decision scenarios. Customer choices are preferences, never evidence. */
const decisionCases={
  acquisition:{label:'咨询是否有效',title:'广告平台记录的这些转化，哪些是真实有效的咨询？',type:'verify',cards:['mix','funnel','trend','device','journey'],gap:'还没确认这些转化是否有效，暂时不能算出获得一个真实客户要花多少钱。',question:'这次你更关心哪一件事？',choices:[['quality','先核实转化有效性','逐条核实转化','先补有效性证据，暂不改变预算。'],['budget','先控制投入风险','核实与预算试验分开','可比较预算上限，但不能预估真实节省或商机损失。']]},
  content:{label:'内容推进',title:'已有的内容，怎样更快产生价值？',type:'content',cards:['content','organic','ranking','journey'],gap:'文章发布后，还要检查能否正常打开、搜索引擎能否读取，以及有没有带来访问。',question:'你希望先解决审核积压，还是检查已发布内容？',choices:[['review','推进待审核内容','优先完成审核','减少等待；发布之后仍需检查页面和抓取结果。'],['published','检查已发布内容','先核实发布结果','先确认页面可访问与内容正确；本轮不会增加新内容产出。']]},
  brand:{label:'品牌认知',title:'客户问 AI 时，会怎样认识我们？',type:'geo',cards:['heatmap','citations','competition','journey'],gap:'目前是模拟回答，可以检查表达与引用，不能据此评价真实品牌增长。',question:'你想先了解回答内容，还是设计持续观察方案？',choices:[['answers','先检查回答内容','逐条审阅问题与回答','定位遗漏、表述及引用问题；不将模拟样本当成正式结论。'],['baseline','先记录现在的表现','使用相同问题和 AI 平台','先保证前后可比较，再判断是否改善；需要后续真实观测。']]}
};
const decision={active:null,stage:0,choices:{},allCharts:true};
const commandLog=[];
function dBattleSummary(){const v=pStats(),articles=pRows('content'),words=pRows('keywords'),published=articles.filter(r=>r.status==='已发布').length,review=articles.filter(r=>r.status==='待审核').length,top10=words.filter(r=>r.rank<=10).length;
 return `<div class="battle-grid"><section class="battle-success"><header><span class="battle-dot"></span><h2>正在积累的成果</h2><small>当前范围</small></header><div class="battle-numbers"><button data-pano="detail" data-value="organic"><b>${pOrganic(v.organic)}</b><span>搜索结果带来的点击 ↗</span><small>${v.organic===null?'当前主题点击未提供':'整站期间合计 · 演示'}</small></button><button data-pano="subset" data-value="content|已发布"><b>${published}<em>篇</em></b><span>内容已发布 ↗</span><i><u style="width:${articles.length?published/articles.length*100:0}%"></u></i><small>${published}/${articles.length} 篇内容记录</small></button><button data-pano="subset" data-value="ranking|Top 10"><b>${words.length?top10:'—'}<em>词</em></b><span>进入搜索前十 ↗</span><i><u style="width:${words.length?top10/words.length*100:0}%"></u></i><small>${words.length?'09.06 排名记录':'范围内无排名记录'}</small></button></div><footer>点击、发布、排名分别衡量，业务效果继续跟进。</footer></section><section class="battle-attention"><header><span class="battle-dot"></span><h2>需要推进的事</h2><small>尚未确认，不代表有问题</small></header><button class="battle-alert" data-decision="start" data-value="acquisition"><b>${v.conv}</b><span>平台记录的转化待确认<small>SEM · 不等于有效线索</small></span><em>核查 →</em></button><button class="battle-alert" data-decision="start" data-value="content"><b>${review}</b><span>内容等待审核<small>推进下一批发布</small></span><em>安排 →</em></button><button class="battle-alert due" data-task="EX-104"><b>2<small>天</small></b><span>这批图片修复后还需检查<small>还有 8 张待检查 · 不受日期筛选影响</small></span><em>09.08 到期 →</em></button><footer>到期提示以演示日期 09.06 为基准。</footer></section></div><div class="command-strip"><div><span class="command-symbol">⌘</span><span>当前正在查看<strong id="commandTarget">${panoCards[pano.focus][1]}</strong></span></div><nav aria-label="数据指令">${['查看依据','比较范围','安排跟进','查看行动'].map((l,i)=>`<button data-command="${['inspect','compare','plan','tasks'][i]}">${l}<span>↗</span></button>`).join('')}</nav></div><div id="commandFeedback" class="command-feedback" role="status">${commandLog.length?esc(commandLog[commandLog.length-1]):'选择图表或数据，即可发起指令 · 原型演练'}</div><div class="d-chart-heading"><h2>经营全景</h2><span>SEM / SEO / GEO · 联动探索</span></div>`;
}
function dButton(label,action,value=''){return `<button data-decision="${action}" data-case="${decision.active||''}" data-value="${esc(value)}">${label}</button>`;}
function dFacts(key){const v=pStats();if(key==='acquisition')return `<b>${money(v.cost)}</b> 投放花费 · <b>${v.conv}</b> 次报表转化`;
 if(key==='content')return `<b>${pRows('content').filter(r=>r.status==='待审核').length}</b> 篇待审核 · <b>${pRows('content').filter(r=>r.status==='已发布').length}</b> 篇已发布`;
 return `<b>${v.mentions}/${v.a.length}</b> 回答提及 · <b>${v.citations}</b> 条自有域引用`;}
function dRender(){if(!panoPage.querySelector('.p-heading'))return;const heading=panoPage.querySelector('.p-heading');heading.querySelector('h1').textContent=decision.active?'把这件事，一起看清楚。':'增长在推进，关键事项别错过。';heading.querySelector('p').textContent='诺德新材料 · 当前演示周期 08.31—09.06';
 let section=panoPage.querySelector('#decisionDesk');if(!section){section=document.createElement('section');section.id='decisionDesk';panoPage.querySelector('.p-kpis').before(section);}
 if(!decision.active){section.innerHTML=dBattleSummary();}
 else{const c=decisionCases[decision.active],choice=c.choices.find(x=>x[0]===decision.choices[decision.active]);section.innerHTML=`<div class="d-current"><div class="d-current-top"><span>正在讨论 / ${c.label}</span>${dButton('返回总览','home')}</div><h2>${c.title}</h2><p>${dFacts(decision.active)} <span>· ${pScope()}</span></p><div class="d-stages">${['看看数据','补充信息','比较做法','安排下一步'].map((l,i)=>`<button data-decision="stage" data-value="${i}" aria-current="${decision.stage===i?'step':'false'}"><i>${i+1}</i>${l}</button>`).join('')}</div><div class="d-condition"><span>还需确认</span>${c.gap}</div>${choice?`<div class="d-preference">你的关注：<b>${choice[1]}</b> · ${choice[3]} ${dButton('调整关注','stage','1')}</div>`:''}</div><div class="d-chart-heading"><h2>${decision.allCharts?'完整经营全景':'这件事的相关依据'}</h2>${dButton(decision.allCharts?'只看相关图表':`展开全部 ${Object.keys(panoCards).length} 张图表`,'charts')}</div>`;}
 panoPage.querySelectorAll('.p-card').forEach(card=>{card.hidden=!!decision.active&&!decision.allCharts&&!decisionCases[decision.active].cards.includes(card.dataset.card);});
}
const dOriginalRender=renderPanorama;renderPanorama=function(){dOriginalRender();dRender();};
function dStart(key){decision.active=key;decision.stage=0;decision.allCharts=false;navigate('panorama');dStep(0);$('#pageScroll').scrollTop=0;}
function dStep(step){if(!decision.active)return;const key=decision.active,c=decisionCases[key];decision.stage=step;renderPanorama();showChat();let html='';const selected=c.choices.find(x=>x[0]===decision.choices[key]);
 if(step===0)html=`<div class="d-message-label">${c.label} / 看看数据</div><h2>${c.title}</h2><p>${pScope()}：${dFacts(key)}。</p><p><strong>目前能确认：</strong>${key==='acquisition'?'这些是报表里的投入与报表转化。':key==='content'?'内容处于不同工作阶段，搜索点击另有独立记录。':'回答可以逐条追查问题、引擎、原文和引用。'}</p><p><strong>还不能确认：</strong>${c.gap}</p><div class="d-chat-actions">${dButton('下一步，明确判断条件','stage','1')}${dButton('先打开原始依据','evidence')}</div>`;
 if(step===1)html=`<div class="d-message-label">${c.label} / 补充信息</div><p>${c.gap}</p><h2>${c.question}</h2><p>先明确你的关注，后面的建议才能围绕这件事展开。</p><div class="d-choice-list">${c.choices.map(x=>`<button data-decision="choose" data-case="${key}" data-value="${x[0]}"><b>${x[1]} →</b><small>${x[3]}</small></button>`).join('')}</div>`;
 if(step===2)html=`<div class="d-message-label">${c.label} / 比较做法</div><p>${selected?`你更关心<strong>${selected[1]}</strong>。这是你的决策偏好，不是数据结论。`:'两种路径可以比较；先选择关注点，建议才有明确方向。'}</p><div class="d-option-grid">${c.choices.map(x=>`<div class="${selected?.[0]===x[0]?'selected':''}"><span>${selected?.[0]===x[0]?'当前选择':'另一条路径'}</span><h3>${x[2]}</h3><p>${x[3]}</p>${dButton(selected?.[0]===x[0]?'按这条路径安排下一步':'选择这条路径',selected?.[0]===x[0]?'stage':'choose',selected?.[0]===x[0]?'3':x[0])}</div>`).join('')}</div><p>无论选择哪条路径，都保留原始范围与完成标准。证据补齐后可以重新判断。</p>`;
 if(step===3){if(!selected){dStep(1);return;}html=`<div class="d-message-label">${c.label} / 安排下一步</div><h2>${selected[2]}</h2><p>范围：${pScope()}<br>你的关注：${selected[1]}</p><p><strong>取舍：</strong>${selected[3]}</p><p>接下来核对负责人、检查日期和完成标准。保存后进入台账，后续可从原业务范围继续讨论。</p><div class="d-chat-actions">${dButton('核对并保存行动','draft')}${key==='acquisition'&&selected[0]==='budget'?dButton('先用滑块比较预算上限','budget'):''}${dButton('再比较一下','stage','2')}</div>`;}
 addMessage('assistant',html);$('#contextTitle').textContent=`${c.label} · ${pScope()} · ${['看看数据','补充信息','比较做法','安排下一步'][step]}`;
 $('#chatSuggestions').innerHTML=['先看原始依据','这个判断有什么风险？','下一步怎么做？'].map(q=>`<button data-question="${q}">${q}</button>`).join('');
}
const dOriginalReply=reply;reply=function(q){if(state.page==='panorama'){const target=/品牌|提及|GEO|geo/.test(q)?'brand':/内容|文章|SEO|seo/.test(q)?'content':/获客|投放|SEM|sem/.test(q)?'acquisition':null;if(target&&target!==decision.active){addMessage('user',q);dStart(target);return;}}if(state.page!=='panorama'||!decision.active){dOriginalReply(q);return;}if(/整体|全景|其他事项/.test(q)){decision.active=null;decision.allCharts=true;renderPanorama();dOriginalReply(q);return;}if(/原始|明细/.test(q)){addMessage('user',q);pOpen(decisionCases[decision.active].cards[0]);return;}if(/风险|为什么|条件|原因/.test(q)){addMessage('user',q);dStep(1);return;}if(/下一步|怎么做|方案/.test(q)){addMessage('user',q);dStep(decision.choices[decision.active]?2:1);return;}dOriginalReply(q);};
window.addEventListener('click',e=>{const b=e.target.closest('[data-decision]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.decision,v=b.dataset.value;if(b.dataset.case&&['stage','choose','evidence','draft','budget'].includes(a)){decision.active=b.dataset.case;decision.allCharts=false;}if(a==='start'){addMessage('user',`我们看一下${decisionCases[v].label}`);dStart(v);}else if(a==='home'){decision.active=null;decision.allCharts=true;renderPanorama();$('#contextTitle').textContent=pScope();}else if(a==='stage'){addMessage('user',b.textContent);dStep(Number(v));}else if(a==='choose'){decision.choices[decision.active]=v;addMessage('user',decisionCases[decision.active].choices.find(x=>x[0]===v)[1]);dStep(2);}else if(a==='charts'){decision.allCharts=!decision.allCharts;dRender();}else if(a==='evidence')pOpen(decisionCases[decision.active].cards[0]);else if(a==='budget'){acquisition.start=pano.start;acquisition.end=pano.end;navigate('acquisition');renderAcquisition();}else if(a==='draft'){const c=decisionCases[decision.active],x=c.choices.find(row=>row[0]===decision.choices[decision.active]);pPlan(c.type);const f=$('#pPlanForm');f.dataset.decisionChoice=x[0];f.elements.title.value=x[2];f.elements.note.value=`讨论范围：${pScope()}。客户关注：${x[1]}。\n取舍：${x[3]}\n${f.elements.note.value}`;if(x[0]==='published')f.elements.note.value=`讨论范围：${pScope()}。逐篇检查已发布页面的可访问性、内容事实与重新抓取结果，记录未通过项。`;if(x[0]==='answers')f.elements.note.value=`讨论范围：${pScope()}。逐条审阅模拟回答的表述、品牌遗漏及引用情况，只形成问题清单，不计算真实品牌效果。`;if(x[0]==='published')f.elements.criterion.value='已发布页面逐篇有可访问性与抓取结论，未通过项有原因和检查安排。';if(x[0]==='answers')f.elements.criterion.value='每条问题保留回答编号、原文、问题描述和建议；模拟回答不计入正式指标。';}},true);
const dOriginalReset=resetChat;resetChat=function(){decision.active=null;decision.stage=0;decision.allCharts=true;dOriginalReset();$('#chatStream').replaceChildren();addMessage('assistant',`<h2>今天想先看什么？</h2><p>已发布 <strong>${pRows('content').filter(r=>r.status==='已发布').length} 篇</strong> · 自然搜索 <strong>${pStats().organic} 次点击</strong></p><p class="chat-priority">待跟进：<strong>${pStats().conv} 次转化核实</strong>；这批图片 <strong>09.08 检查</strong>。</p><div class="d-chat-actions">${dButton('看看咨询是否有效','start','acquisition')}${dButton('处理内容进度','start','content')}${dButton('了解品牌回答','start','brand')}</div>`);$('#chatStream').scrollTop=0;};
function commandFeedback(message){commandLog.push(message);const feedback=$('#commandFeedback');if(feedback){feedback.textContent=message;feedback.classList.remove('command-arrived');void feedback.offsetWidth;feedback.classList.add('command-arrived');}}
const commandOpenEvidence=pOpen;pOpen=function(...args){commandOpenEvidence(...args);const target=$('#commandTarget');if(target)target.textContent=panoCards[pano.focus][1];};
function runDataCommand(action){const target=panoCards[pano.focus][1];if(action==='inspect'){pOpen(pano.focus);addMessage('assistant',`<p>已打开<strong>${esc(target)}</strong>的原始依据，范围：${pScope()}。你可以点记录继续追查，或带入对话讨论。</p>`);commandFeedback(`已打开依据 · ${target} · ${pScope()}`);}else if(action==='compare'){const hadBaseline=!!pano.compare;pCompare();commandFeedback(hadBaseline?'已打开两个范围的并排比较':'已固定当前范围。切换主题或日期，再点“比较范围”。');}else if(action==='plan'){pPlan(pano.focus);commandFeedback(`已打开跟进方案 · ${target} · 等待确认`);}else if(action==='tasks'){navigate('tasks');addMessage('assistant','<p>待办与进度已打开。可以分别查看待确认方案、执行进度和结果检查情况。</p>');}}
window.addEventListener('click',e=>{const card=e.target.closest('.p-card');if(card){pano.focus=card.dataset.card;panoPage.querySelectorAll('.p-card').forEach(c=>c.classList.toggle('is-focused',c===card));const target=$('#commandTarget');if(target)target.textContent=panoCards[pano.focus][1];pContext();}const b=e.target.closest('[data-command]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();addMessage('user',`${b.textContent.replace('↗','').trim()}：${panoCards[pano.focus][1]}`);runDataCommand(b.dataset.command);},true);
const guidedCommandReply=reply;reply=function(q){if(state.page==='panorama'){const command=/^(核查|查看|查一下)(当前|这张|这个)?(数据|图表|依据)/.test(q)?'inspect':/^比较(当前|这两|范围)/.test(q)?'compare':/^(安排|创建)(跟进|行动)/.test(q)?'plan':/^(查看行动|看执行结果)/.test(q)?'tasks':null;if(command){addMessage('user',q);runDataCommand(command);return;}}guidedCommandReply(q);};
resetChat();
